import React, { useState, useEffect } from "react";
import Avatar from "./Avatar";
import { useAuth } from "../context/AuthContext";
import { getRoomName, fmtTime, initials } from "../utils/helpers";
import { getAllUsers, createRoom } from "../services/api";

export default function Sidebar({ rooms, activeRoomId, onSelectRoom, onRoomsChange, wsConnected, messages, unread = {} }) {
  const { username, signOut } = useAuth();
  const [search, setSearch]   = useState("");
  const [showModal, setShowModal] = useState(false);

  const filtered = rooms.filter((r) =>
    getRoomName(r, username).toLowerCase().includes(search.toLowerCase())
  );

  return (
    <>
      <aside className="w-72 lg:w-80 flex-shrink-0 bg-crisp-surface border-r border-crisp-border
        flex flex-col h-full overflow-hidden">

        {/* Header */}
        <div className="px-4 pt-5 pb-4 border-b border-crisp-border">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 bg-crisp-accent rounded-xl flex items-center justify-center
              font-mono font-bold text-white text-sm shadow-md shadow-crisp-accent/25">C</div>
            <div className="flex-1 min-w-0">
              <div className="font-display font-bold text-base text-crisp-text">Crisp</div>
              <div className="flex items-center gap-1.5 mt-0.5">
                <span className={`w-1.5 h-1.5 rounded-full transition-colors
                  ${wsConnected ? "bg-crisp-green" : "bg-crisp-amber"}`} />
                <span className="text-xs text-crisp-muted font-mono">
                  {wsConnected ? "Connected" : "Connecting..."}
                </span>
              </div>
            </div>
            <button onClick={signOut}
              className="w-8 h-8 rounded-lg bg-crisp-card hover:bg-crisp-hover border border-crisp-border
                flex items-center justify-center text-crisp-muted hover:text-crisp-sub transition-all"
              title="Sign out">
              <LogoutIcon />
            </button>
          </div>

          {/* Current user pill */}
          <div className="flex items-center gap-2.5 mt-4 bg-crisp-card border border-crisp-border
            rounded-xl px-3 py-2.5">
            <Avatar name={username} size="sm" online />
            <div className="flex-1 min-w-0">
              <div className="text-sm font-display font-semibold text-crisp-text truncate">{username}</div>
              <div className="text-xs text-crisp-green font-mono">● Online</div>
            </div>
          </div>
        </div>

        {/* Search */}
        <div className="px-4 py-3 border-b border-crisp-border">
          <div className="relative">
            <SearchIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-crisp-muted" />
            <input className="input-field pl-9 text-sm" placeholder="Search conversations..."
              value={search} onChange={(e) => setSearch(e.target.value)} />
          </div>
        </div>

        {/* Room list */}
        <div className="flex-1 overflow-y-auto px-2 py-2">
          {filtered.length === 0 ? (
            <div className="text-center py-8 text-crisp-muted text-sm font-body">
              {search ? "No results" : "No conversations yet"}
            </div>
          ) : (
            <div className="space-y-0.5">
              {filtered.map((room) => (
                <RoomItem
                  key={room.id}
                  room={room}
                  active={room.id === activeRoomId}
                  onClick={() => onSelectRoom(room)}
                  username={username}
                  lastMsg={(messages[room.id] || []).slice(-1)[0]}
                  unreadCount={unread[room.id] || 0}
                />
              ))}
            </div>
          )}
        </div>

        {/* New chat */}
        <div className="p-4 border-t border-crisp-border">
          <button onClick={() => setShowModal(true)}
            className="w-full flex items-center justify-center gap-2 py-2.5 rounded-xl
              bg-crisp-accent/10 hover:bg-crisp-accent/20 border border-crisp-accent/25
              text-crisp-accent2 font-display font-semibold text-sm transition-all duration-200">
            <PlusIcon className="w-4 h-4" />
            New Conversation
          </button>
        </div>
      </aside>

      {showModal && (
        <NewChatModal
          onClose={() => setShowModal(false)}
          onCreated={(room) => { onRoomsChange(room); setShowModal(false); onSelectRoom(room); }}
          myUsername={username}
          existingRooms={rooms}
        />
      )}
    </>
  );
}

// ── Room item with unread badge ───────────────────────────────────────────────
function RoomItem({ room, active, onClick, username, lastMsg, unreadCount }) {
  const name    = getRoomName(room, username);
  const isGroup = room.isGroup || room.group;
  const preview = lastMsg
    ? `${lastMsg.senderId === username ? "You: " : ""}${lastMsg.content}`
    : "No messages yet";

  return (
    <div className={`room-item ${active ? "active" : ""}`} onClick={onClick}>
      <Avatar name={name} size="md" square={isGroup} />
      <div className="flex-1 min-w-0">
        <div className="flex items-baseline justify-between gap-2">
          <span className={`text-sm font-display font-semibold truncate
            ${unreadCount > 0 ? "text-crisp-text" : "text-crisp-text"}`}>
            {name}
          </span>
          {lastMsg?.timestamp && (
            <span className={`text-[10px] flex-shrink-0 font-mono
              ${unreadCount > 0 ? "text-crisp-accent2" : "text-crisp-muted"}`}>
              {fmtTime(lastMsg.timestamp)}
            </span>
          )}
        </div>
        <div className="flex items-center justify-between gap-2 mt-0.5">
          <div className={`text-xs truncate font-body
            ${unreadCount > 0 ? "text-crisp-sub font-medium" : "text-crisp-muted"}`}>
            {preview}
          </div>
          {/* Feature: unread badge */}
          {unreadCount > 0 && (
            <span className="flex-shrink-0 min-w-[20px] h-5 px-1.5 rounded-full
              bg-crisp-accent text-white text-[10px] font-mono font-bold
              flex items-center justify-center animate-fadeIn">
              {unreadCount > 99 ? "99+" : unreadCount}
            </span>
          )}
        </div>
      </div>
    </div>
  );
}

// ── New Chat Modal (unchanged from previous version) ─────────────────────────
function NewChatModal({ onClose, onCreated, myUsername, existingRooms }) {
  const [type, setType]           = useState("dm");
  const [users, setUsers]         = useState([]);
  const [selected, setSelected]   = useState([]);
  const [groupName, setGroupName] = useState("");
  const [loading, setLoading]     = useState(false);
  const [error, setError]         = useState("");
  const [usersLoading, setUsersLoading] = useState(true);

  useEffect(() => {
    getAllUsers()
      .then(({ data }) => setUsers(data.filter((u) => u.username !== myUsername)))
      .catch(() => setError("Could not load users"))
      .finally(() => setUsersLoading(false));
  }, [myUsername]);

  const toggle = (uname) => {
    if (type === "dm") { setSelected([uname]); return; }
    setSelected((prev) =>
      prev.includes(uname) ? prev.filter((u) => u !== uname) : [...prev, uname]
    );
  };

  const handleCreate = async () => {
    if (!selected.length) { setError("Select at least one user"); return; }
    if (type === "group" && !groupName.trim()) { setError("Enter a group name"); return; }
    setLoading(true); setError("");
    try {
      const body = {
        participantIds: [myUsername, ...selected],
        isGroup: type === "group",
        ...(type === "group" && { name: groupName.trim() }),
      };
      const { data } = await createRoom(body);
      onCreated(data);
    } catch (err) {
      const msg = err.response?.data?.error || "";
      if (msg.includes("already exists")) {
        const ex = existingRooms.find(
          (r) => !(r.isGroup || r.group) && r.participantIds?.includes(selected[0])
        );
        if (ex) { onCreated(ex); return; }
      }
      setError(msg || "Failed to create room");
    } finally { setLoading(false); }
  };

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4"
      onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div className="bg-crisp-surface border border-crisp-border rounded-2xl p-6 w-full max-w-sm shadow-2xl animate-slideUp">
        <div className="flex items-center justify-between mb-5">
          <h2 className="font-display font-bold text-lg text-crisp-text">New Conversation</h2>
          <button onClick={onClose} className="w-7 h-7 rounded-lg bg-crisp-card hover:bg-crisp-hover
            flex items-center justify-center text-crisp-muted text-lg leading-none transition-all">×</button>
        </div>
        <div className="flex bg-crisp-bg rounded-xl p-1 mb-5 border border-crisp-border">
          {["dm", "group"].map((t) => (
            <button key={t} onClick={() => { setType(t); setSelected([]); }}
              className={`flex-1 py-2 rounded-lg font-display font-semibold text-xs transition-all
                ${type === t ? "bg-crisp-accent text-white" : "text-crisp-muted hover:text-crisp-sub"}`}>
              {t === "dm" ? "Direct Message" : "Group Chat"}
            </button>
          ))}
        </div>
        {type === "group" && (
          <div className="mb-4">
            <label className="block text-xs font-display font-semibold text-crisp-muted uppercase tracking-widest mb-2">Group Name</label>
            <input className="input-field" placeholder="Team Alpha, Weekend Plans..."
              value={groupName} onChange={(e) => setGroupName(e.target.value)} />
          </div>
        )}
        <label className="block text-xs font-display font-semibold text-crisp-muted uppercase tracking-widest mb-2">
          {type === "dm" ? "Select User" : "Add Participants"}
        </label>
        <div className="bg-crisp-bg border border-crisp-border rounded-xl overflow-hidden max-h-48 overflow-y-auto mb-4">
          {usersLoading ? (
            <div className="py-6 text-center text-crisp-muted text-sm">Loading users...</div>
          ) : users.length === 0 ? (
            <div className="py-6 text-center text-crisp-muted text-sm px-4">No other users found.</div>
          ) : (
            users.map((u) => {
              const sel = selected.includes(u.username);
              return (
                <div key={u.username} onClick={() => toggle(u.username)}
                  className={`flex items-center gap-3 px-4 py-3 cursor-pointer transition-all
                    ${sel ? "bg-crisp-accent/10" : "hover:bg-crisp-hover"} border-b border-crisp-border/50 last:border-0`}>
                  <Avatar name={u.fullName || u.username} size="sm" />
                  <div className="flex-1 min-w-0">
                    <div className="text-sm font-display font-semibold text-crisp-text truncate">{u.fullName || u.username}</div>
                    <div className="text-xs text-crisp-muted font-mono">@{u.username}</div>
                  </div>
                  <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center text-xs
                    transition-all ${sel ? "bg-crisp-accent border-crisp-accent text-white" : "border-crisp-border2"}`}>
                    {sel && "✓"}
                  </div>
                </div>
              );
            })
          )}
        </div>
        {error && (
          <div className="mb-4 text-red-300 text-sm bg-red-500/10 border border-red-500/20 px-3 py-2 rounded-lg">{error}</div>
        )}
        <div className="flex gap-2">
          <button onClick={onClose} className="btn-ghost flex-1">Cancel</button>
          <button onClick={handleCreate} disabled={loading} className="btn-primary flex-1">
            {loading ? "Creating..." : "Create Chat"}
          </button>
        </div>
      </div>
    </div>
  );
}

// Icons
const SearchIcon = ({ className }) => (
  <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
    <circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/>
  </svg>
);
const PlusIcon = ({ className }) => (
  <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
    <path d="M12 5v14M5 12h14"/>
  </svg>
);
const LogoutIcon = () => (
  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
    <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/>
    <polyline points="16 17 21 12 16 7"/>
    <line x1="21" y1="12" x2="9" y2="12"/>
  </svg>
);
